async function main() {
  console.log("Seeding MedEx Bangladesh 540+ authentic products catalog...");

  const saltRounds = Number(process.env.BCRYPT_SALT_ROUNDS) || 10;
  const hashPassword = (pw: string) => bcrypt.hashSync(pw, saltRounds);

  // 1. Roles & Default Users
  const roles = [
    { name: "Super Admin", email: "admin@medistore.com", role: "ADMIN", phone: "01700000001", address: "Dhaka, Bangladesh" },
    { name: "Demo Customer", email: "customer1@example.com", role: "CUSTOMER", phone: "01700000002", address: "Banani, Dhaka" },
    { name: "Demo Rider", email: "rider1@example.com", role: "RIDER", phone: "01700000003", address: "Gulshan, Dhaka" },
  ];

  for (const u of roles) {
    const existing = await prisma.user.findUnique({ where: { email: u.email } });
    if (!existing) {
      await prisma.user.create({
        data: {
          name: u.name,
          email: u.email,
          password: hashPassword("@Rifat1234"),
          role: u.role as any,
          phone: u.phone,
          address: u.address,
        },
      });
    }
  }

  // 2. Department Categories
  const categoriesData = [
    { name: "Medicines", imageUrl: "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=600&auto=format&fit=crop&q=80" },
    { name: "Baby & Mom", imageUrl: "https://images.unsplash.com/photo-1515488042361-ee00e0ddd4e4?w=600&auto=format&fit=crop&q=80" },
    { name: "Diabetic Care", imageUrl: "https://images.unsplash.com/photo-1584017911766-d451b3d0e843?w=600&auto=format&fit=crop&q=80" },
    { name: "Health & Devices", imageUrl: "https://images.unsplash.com/photo-1584515933487-779824d29309?w=600&auto=format&fit=crop&q=80" },
    { name: "Personal Care", imageUrl: "https://images.unsplash.com/photo-1556228720-195a672e8a03?w=600&auto=format&fit=crop&q=80" },
    { name: "Vital Wellness", imageUrl: "https://images.unsplash.com/photo-1584362917165-526a968579e8?w=600&auto=format&fit=crop&q=80" },
  ];

  const categoryMap: Record<string, string> = {};

  for (const cat of categoriesData) {
    const upserted = await prisma.category.upsert({
      where: { name: cat.name },
      update: { imageUrl: cat.imageUrl },
      create: { name: cat.name, imageUrl: cat.imageUrl },
    });
    categoryMap[cat.name] = upserted.id;
  }

  // 3. Upsert 540 MedEx products into database
  console.log("Upserting " + MEDEX_PRODUCTS_540.length + " MedEx products into database...");
  const futureExpiry = new Date();
  futureExpiry.setFullYear(futureExpiry.getFullYear() + 2);

  for (const p of MEDEX_PRODUCTS_540) {
    const targetCatId = categoryMap[p.categoryName] || categoryMap["Medicines"];
    await prisma.medicine.create({
      data: {
        name: p.name,
        manufacturer: p.manufacturer,
        price: p.price,
        stock: p.stock,
        requiredPrescription: p.requiredPrescription,
        imageUrl: p.imageUrl,
        description: p.description,
        expiryDate: futureExpiry,
        categoryId: targetCatId,
      },
    });
  }

  console.log("✅ Successfully seeded 540 authentic MedEx products into PostgreSQL DB!");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
    await pool.end();
  });
